<?php
require __DIR__.'/_common.php'; admin_require(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);if($action==='delete'){$pdo->prepare('DELETE FROM games WHERE id=?')->execute([$id]);flash('Jeu supprimé');redirect_self();}if($action==='toggle'){$pdo->prepare('UPDATE games SET active=1-active WHERE id=?')->execute([$id]);flash('Statut modifié');redirect_self();}$name=trim((string)$_POST['name']);$slug=trim((string)$_POST['slug']);$desc=trim((string)$_POST['description']);$active=isset($_POST['active'])?1:0;if($id){$pdo->prepare('UPDATE games SET name=?,slug=?,description=?,active=? WHERE id=?')->execute([$name,$slug,$desc,$active,$id]);}else{$pdo->prepare('INSERT INTO games(name,slug,description,active) VALUES(?,?,?,?)')->execute([$name,$slug,$desc,$active]);}flash('Jeu enregistré');redirect_self();}$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM games WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$games=$pdo->query('SELECT * FROM games ORDER BY name')->fetchAll();admin_layout_start('Jeux');echo '<form method="post" class="form"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="hidden" name="id" value="'.h($edit['id']??0).'"><input name="name" placeholder="Nom" value="'.h($edit['name']??'').'" required><input name="slug" placeholder="Slug" value="'.h($edit['slug']??'').'" required><input name="description" placeholder="Description" value="'.h($edit['description']??'').'"><label><input type="checkbox" name="active" '.(!isset($edit)||!empty($edit['active'])?'checked':'').'> Actif</label><button>Enregistrer</button></form><table><tr><th>Nom</th><th>Slug</th><th>Description</th><th>Actif</th><th>Actions</th></tr>';foreach($games as $g)echo '<tr><td>'.h($g['name']).'</td><td>'.h($g['slug']).'</td><td>'.h($g['description']??'').'</td><td>'.(!empty($g['active'])?'Oui':'Non').'</td><td><a href="?edit='.h($g['id']).'">Modifier</a> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="hidden" name="id" value="'.h($g['id']).'"><input type="hidden" name="action" value="toggle"><button>Activer/Désactiver</button></form> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="hidden" name="id" value="'.h($g['id']).'"><input type="hidden" name="action" value="delete"><button onclick="return confirm(\'Supprimer ?\')">Supprimer</button></form></td></tr>';echo '</table>';admin_layout_end();